<div class="page-heading"><div><a class="back-link" href="/<?= e($resource->key) ?>">← Kembali ke <?= e($resource->title) ?></a><h1><?= e($title) ?></h1><p>Informasi lengkap data #<?= (int)$row['id'] ?></p></div><?php if($canWrite): ?><a class="btn btn-primary" href="/<?= e($resource->key) ?>/<?= (int)$row['id'] ?>/edit">Edit data →</a><?php endif; ?></div><section class="panel form-panel"><?php if($resource->key === 'barang'): ?><img class="item-photo mb-4" src="<?= e(\App\Helpers\InventoryPresentation::photo($row)) ?>" data-fallback="<?= e(\App\Helpers\InventoryPresentation::placeholder($row['kategori'])) ?>" alt="<?= e($row['nama_barang']) ?>"><?php endif; ?><dl class="detail-grid"><?php foreach($row as $name=>$value): if($name==='foto')continue; $field=$resource->fields[$name]??null; ?><div><dt><?= e($field['label']??ucwords(str_replace('_',' ',$name))) ?></dt><dd><?= e(($field['type']??'')==='select'?($options[$field['source']][$value]??'—'):($value??'—')) ?></dd></div><?php endforeach; ?></dl></section>
